window.CourseData=window.CourseData||{};window.CourseData["electrical-safety-osha"]={"slug":"electrical-safety-osha","title":"Electrical Safety and OSHA Standards","short":"Electrical Safety & OSHA","hours":4,"edition":0,"scope":"multi","audience":"Journeyman & Master Electrician","articles":"OSHA 29 CFR 1910 Subpart S, 1926 Subpart K","free":false,"labs":[],"slideMin":150,"modules":[{"title":"OSHA Framework and Electrical Hazards","minutes":60,"overview":["The OSH Act, general duty and the electrical standards","How Subpart S and Subpart K are organized","Definitions: qualified and unqualified persons","Electrical hazards: shock, electrocution, burns, arc flash, falls","Inspections, citations and employee rights"],"slides":[{"title":"The OSH Act and the general duty","body":"The Occupational Safety and Health Act of 1970 requires employers to provide a workplace free from recognized hazards that are likely to cause death or serious harm, and to comply with OSHA standards. Employees must comply with the rules that apply to their own conduct.","info":"Section numbers in this course are given for orientation. When a decision matters, read the current text at osha.gov or ecfr.gov and your state plan, if you have one.","bullets":["General Duty Clause (Section 5(a)(1)): protect workers from recognized serious hazards even where no specific standard applies.","Specific standards (29 CFR) set detailed requirements, such as lockout/tagging and protective equipment.","State plans: some states run their own OSHA-approved programs that must be at least as effective. Public-sector coverage and some details differ by state.","Courses like this one teach the standards for orientation; the CFR text controls."],"refs":["OSH Act Section 5","29 CFR 1910","29 CFR 1926"],"checks":[{"q":"The General Duty Clause requires employers to","opts":["Protect workers from recognized serious hazards even where no specific standard exists","Only follow specific standards","Pay for all training","Report to the electrician board"],"correct":0,"explain":"Section 5(a)(1) covers recognized hazards without a specific standard.","ref":"OSH Act 5(a)(1)"}]},{"title":"General industry and construction","body":"OSHA has separate rule sets for general industry and for construction. Know which one applies to the work you are doing.","keypoint":"Electrical contractors working on a construction site are usually under the construction standards even when the work is electrical.","table":{"h":["Area","General industry","Construction"],"r":[["Electrical design and installation","29 CFR 1910.302-.308 (Subpart S)","29 CFR 1926.402-.408 (Subpart K)"],["Safety-related work practices","1910.331-.335","1926.416, .417 (and other Subpart K sections)"],["Electric power generation, transmission and distribution","1910.269","1926 Subpart V"],["Lockout/tagout","1910.333(b) for electrical work, 1910.147 for other energy sources","1926.417"]]},"refs":["29 CFR 1910 Subpart S","29 CFR 1926 Subpart K","29 CFR 1910.269"],"checks":[{"q":"Electric power transmission and distribution work in general industry is covered mainly by","opts":["29 CFR 1910.269","1910.147 only","1910.95","1926.20"],"correct":0,"explain":"1910.269 covers electric power generation, transmission and distribution.","ref":"1910.269"}]},{"title":"Inside Subpart S","body":"Subpart S divides electrical rules into design safety standards for installations and safety-related work practices.","def_grid":[{"term":"Design safety (1910.302-.308)","body":"Rules for electric utilization systems: general requirements, wiring design and protection, wiring methods, hazardous locations and special systems. These follow the National Electrical Code in many places."},{"term":"Safety-related work practices (1910.331-.335)","body":"How employees must work: training, deenergizing and lockout/tagging, working near energized parts, using equipment and personal protective gear."},{"term":"Definitions (1910.399)","body":"Definitions such as qualified person, energized, and exposed."}],"refs":["29 CFR 1910.301-.399"],"checks":[{"q":"Which part of Subpart S covers how employees must work around electrical hazards?","opts":["The safety-related work practices (1910.331-.335)","The design standards only","1910.399","1910.147"],"correct":0,"explain":"The work practices sections set rules for training, lockout and protective equipment.","ref":"1910.331"}]},{"title":"Who is covered by the work practices","body":"The work practices in 1910.331 through 1910.335 cover electrical safety-related work practices for employees who face a risk of electric shock, burns or other injury from electrical hazards, and work near or on equipment.","bullets":["Covered: employees working on or near exposed energized parts, and employees who work on electrical equipment.","Not covered by 1910.331-.335: electric utility power generation, transmission and distribution work covered by 1910.269.","Employers with workers who may work around electricity must train them in the hazards and practices that apply to their job."],"refs":["29 CFR 1910.331","29 CFR 1910.332"],"checks":[{"q":"Utility work on transmission and distribution lines is addressed primarily by","opts":["1910.269","1910.332","1910.147","The NEC"],"correct":0,"explain":"1910.269 covers electric power generation, transmission and distribution.","ref":"1910.269"}]},{"title":"Qualified and unqualified persons","body":"OSHA draws a line between those who may work on exposed energized parts and those who may not. The definitions are in 1910.399.","keypoint":"Only qualified persons may work on or near exposed energized parts that have not been deenergized, 1910.333(c)(2).","def_grid":[{"term":"Qualified person","body":"One who has received training in and has demonstrated skills and knowledge in the construction and operation of electric equipment and installations and the hazards involved."},{"term":"Unqualified person","body":"Anyone who does not meet that standard for the equipment and task. They must be kept away from exposed energized parts."},{"term":"Task specific","body":"Qualification depends on the equipment and the work. A person may be qualified for some tasks and not others."}],"refs":["29 CFR 1910.399","29 CFR 1910.333(c)(2)"],"checks":[{"q":"Under 1910.333, who may work on exposed energized parts that have not been deenergized?","opts":["Only qualified persons","Any employee wearing PPE","Any supervisor","Anyone with an escort"],"correct":0,"explain":"1910.333(c)(2) limits this work to qualified persons.","ref":"1910.333(c)(2)"}]},{"title":"Electrical hazards at work","body":"Electrical hazards cause injury in several ways. Each calls for different controls.","table":{"h":["Hazard","How it harms","Typical control"],"r":[["Shock and electrocution","Current through the body can stop the heart or breathing","Deenergize, GFCI, insulation, grounding, PPE"],["Burns","Contact burns, arc burns, and thermal burns from arcs","Distance, arc-rated clothing, de-energize"],["Arc flash and arc blast","Intense heat and pressure from an arc","De-energize, labeling, arc-rated PPE, engineering controls"],["Falls and secondary injury","Reaction to shock can cause a fall from a ladder or lift","Fall protection, nonconductive ladders, stable work positions"],["Fire and explosion","Overloaded or damaged equipment, hazardous locations","Proper installation, maintenance, listed equipment"]]},"refs":["OSHA electrical safety resources"],"checks":[{"q":"Why can a minor shock still lead to serious injury?","opts":["The reaction may cause a fall or other secondary injury","Voltage is stronger indoors","Shock never matters at low voltage","Only burns matter"],"correct":0,"explain":"Reflex reactions can cause falls or contact with other hazards.","ref":""}]},{"title":"Construction's \"Focus Four\"","body":"OSHA identifies four hazards behind most construction fatalities: falls, struck-by, caught-in or between, and electrocution. Electrocution is one of the four.","bullets":["Contact with overhead power lines is a leading cause of electrocution on construction sites.","Using damaged cords and tools, missing grounding or GFCI protection, and working on circuits assumed to be dead are repeated causes.","Controls: identify and de-energize, keep clearance from lines, use GFCI protection, inspect cords and tools."],"refs":["OSHA Construction Focus Four"],"checks":[{"q":"Which is part of OSHA's Focus Four construction hazards?","opts":["Electrocution","Heat stress","Sunburn","Noise"],"correct":0,"explain":"Falls, struck-by, caught-in/between and electrocution.","ref":""}]},{"title":"OSHA inspections and citations","body":"OSHA may inspect workplaces with or without notice. Citations are classified by the seriousness and the employer's knowledge.","info":"Penalty amounts are adjusted every year. Check OSHA's current penalty table rather than relying on a number in a course.","table":{"h":["Citation type","Meaning"],"r":[["Other-than-serious","Affects safety or health but is unlikely to cause death or serious harm"],["Serious","A substantial probability of death or serious physical harm, and the employer knew or should have known"],["Willful","The employer intentionally disregarded the requirement or showed plain indifference"],["Repeat","The same or a similar violation previously cited"],["Failure to abate","A cited hazard was not corrected by the required date"]]},"refs":["OSH Act Section 9, 17"],"checks":[{"q":"A violation the employer knowingly and intentionally disregarded is classified as","opts":["Willful","Other-than-serious","De minimis","Abated"],"correct":0,"explain":"Willful means intentional disregard or plain indifference.","ref":""}]},{"title":"Employee rights and reporting","body":"Workers have rights under the OSH Act, and employers have reporting duties.","bullets":["Workers may request an OSHA inspection, file a complaint, and talk to the inspector.","Workers are protected from retaliation for exercising these rights. A complaint under Section 11(c) generally must be filed within 30 days.","Employers must report a work-related fatality to OSHA within 8 hours, and an inpatient hospitalization, amputation or loss of an eye within 24 hours (29 CFR 1904.39).","Employers must keep injury and illness records, including the OSHA 300 log, for five years.","Employees may request exposure and medical records related to them."],"refs":["OSH Act Section 11(c)","29 CFR 1904.39"],"checks":[{"q":"An employer must report a work-related fatality to OSHA within","opts":["8 hours","24 hours","7 days","30 days"],"correct":0,"explain":"Fatalities within 8 hours; hospitalizations, amputations and eye loss within 24 hours.","ref":"1904.39"}]},{"title":"State plans and local rules","body":"About half the states run OSHA-approved state plans. Many electricians are also covered by state licensing law, local codes and the employer's own program.","info":"Check which program covers your workplace. A state-plan state may have different penalty amounts, inspection details and extra standards.","bullets":["In a state-plan state, the state agency enforces workplace safety and may set stricter rules.","Federal OSHA covers employers in non-plan states and some federal workplaces.","State and local electrical licensing, and the adopted NEC edition, are separate from OSHA.","Always follow the strictest applicable rule."],"refs":["OSH Act Section 18"],"checks":[{"q":"In a state with an OSHA-approved state plan, workplace safety rules are enforced by","opts":["The state agency, which must be at least as effective as federal OSHA","The federal government only","The employer only","The local inspector only"],"correct":0,"explain":"State plans are approved by OSHA and must be at least as effective.","ref":""}]}],"quiz":[{"q":"The OSH Act requires employers to provide","opts":["A workplace free from recognized serious hazards","Tools at cost","Free housing","A union"],"correct":0,"explain":"This is the General Duty Clause.","ref":"OSH Act 5(a)(1)"},{"q":"Section 5(a)(1) of the OSH Act is known as","opts":["The General Duty Clause","The Whistleblower Clause","The Penalty Clause","The Recording Rule"],"correct":0,"explain":"It covers recognized hazards without a specific standard.","ref":"OSH Act"},{"q":"Which part covers construction electrical safety?","opts":["29 CFR 1926 Subpart K","1910 Subpart A","1904","1915"],"correct":0,"explain":"Subpart K is construction electrical.","ref":"1926 Subpart K"},{"q":"Which part covers general industry electrical safety?","opts":["29 CFR 1910 Subpart S","1926 Subpart K","1904","1915"],"correct":0,"explain":"Subpart S is general industry electrical.","ref":"1910 Subpart S"},{"q":"1910.331-.335 cover","opts":["Electrical safety-related work practices","Recordkeeping","Respirators","Fall protection"],"correct":0,"explain":"Work practices.","ref":"1910.331"},{"q":"Where are qualified person definitions found?","opts":["1910.399","1910.95","1904.39","1910.147"],"correct":0,"explain":"Definitions are in 1910.399.","ref":"1910.399"},{"q":"A qualified person is","opts":["Trained and has demonstrated skills in the equipment and hazards involved","Anyone who owns tools","Anyone licensed in any state","A new hire"],"correct":0,"explain":"Training and demonstrated skills for the equipment and hazards.","ref":"1910.399"},{"q":"An unqualified person near exposed energized parts must be","opts":["Kept away from the exposed energized parts","Given a hard hat","Allowed to work","Moved closer"],"correct":0,"explain":"Unqualified persons must not work on exposed energized parts.","ref":"1910.333(c)"},{"q":"Which standard covers utility power generation, transmission and distribution?","opts":["1910.269","1910.147","1910.95","1926.20"],"correct":0,"explain":"1910.269 covers these.","ref":"1910.269"},{"q":"Which is in OSHA's construction Focus Four?","opts":["Electrocution","Heat","Noise","Fatigue"],"correct":0,"explain":"Electrocution is one of four.","ref":"OSHA"},{"q":"Contact with overhead power lines is","opts":["A leading cause of electrocution on construction sites","Rare","Only a problem indoors","Only for utilities"],"correct":0,"explain":"Overhead line contact is a common electrocution cause.","ref":"OSHA"},{"q":"Which citation type means the employer intentionally disregarded the rule?","opts":["Willful","Serious","Repeat","Other-than-serious"],"correct":0,"explain":"Willful is intentional disregard.","ref":"OSH Act"},{"q":"Which citation type applies to a repeat of a similar violation?","opts":["Repeat","Willful","De minimis","Other-than-serious"],"correct":0,"explain":"Repeat applies to the same or similar violation previously cited.","ref":"OSH Act"},{"q":"An employer must report a work-related fatality within","opts":["8 hours","24 hours","48 hours","30 days"],"correct":0,"explain":"Report fatalities within 8 hours.","ref":"1904.39"},{"q":"An employer must report an in-patient hospitalization within","opts":["24 hours","8 hours","48 hours","30 days"],"correct":0,"explain":"Hospitalizations, amputations and eye loss within 24 hours.","ref":"1904.39"},{"q":"Section 11(c) protects workers who","opts":["Exercise safety rights from retaliation","Break rules","Skip training","Quit"],"correct":0,"explain":"It prohibits retaliation.","ref":"OSH Act 11(c)"},{"q":"A state plan state","opts":["Enforces its own OSHA-approved program","Has no workplace safety rules","Follows no standards","Uses only federal rules"],"correct":0,"explain":"State plans must be at least as effective.","ref":"OSH Act 18"},{"q":"The OSHA 300 log is generally retained for","opts":["Five years","One year","Ten years","Thirty days"],"correct":0,"explain":"Records are retained for five years after the year they cover.","ref":"1904"}]},{"title":"Safe Work Practices: 1910.331-.335","minutes":60,"overview":["Training requirements","Deenergize first: 1910.333(a)","Lockout and tagging for electrical work","Working on or near energized parts and overhead lines","Portable equipment, test instruments and safeguards"],"slides":[{"title":"Training under 1910.332","body":"Employees who face a risk of electric shock that is not reduced to a safe level by the installation requirements must be trained in the safety-related work practices that apply to their job.","bullets":["Training can be classroom or on-the-job, and must cover the specific hazards and practices of the work.","Qualified persons need training to distinguish exposed live parts, determine nominal voltage, know minimum approach distances and the proper use of precautionary techniques and protective equipment.","Unqualified persons must be trained in and be familiar with any safety-related work practices necessary for their safety.","Table S-4 in 1910.332 lists typical occupations facing a risk of electric shock that need training, such as electricians, electrical engineers, and certain supervisors.","The degree of training is set by the risk to the employee."],"refs":["29 CFR 1910.332"],"checks":[{"q":"A qualified person under 1910.332 must be trained to","opts":["Distinguish exposed live parts and know the minimum approach distances","Install receptacles only","Do payroll","Operate forklifts"],"correct":0,"explain":"Qualified persons must be able to recognize live parts, determine voltage and use required clearances and protection.","ref":"1910.332"}]},{"title":"Deenergize first: 1910.333(a)","body":"The basic rule is that live parts must be deenergized before an employee works on or near them, unless doing so is infeasible or increases the hazard.","keypoint":"Live parts shall be deenergized unless the employer can demonstrate that deenergizing introduces additional or increased hazards or is infeasible because of equipment design or operational limitations.","bullets":["Examples of increased hazards: shutting down life-support systems, emergency alarms, hazardous location ventilation.","Examples of infeasibility: work on circuits of a continuous industrial process that cannot be shut down.","Live parts under 50 volts to ground need not be deenergized if there is no increased exposure to electrical burns or arc explosion.","Convenience and cost are not recognized reasons."],"refs":["29 CFR 1910.333(a)(1)"],"checks":[{"q":"Which is a recognized reason not to deenergize?","opts":["Deenergizing would create an additional hazard, such as shutting off life support","The customer wants no downtime","It is a short job","It is after hours"],"correct":0,"explain":"Increased hazard or infeasibility are the stated reasons.","ref":"1910.333(a)(1)"}]},{"title":"Lockout and tagging: 1910.333(b)","body":"Where employees work on deenergized circuits, a lockout and tagging procedure must be in place. This is the electrical-specific rule for utilization installations.","info":"The general lockout/tagout standard, 1910.147, covers the control of hazardous energy for machines and equipment. It excludes work on electric utilization installations that falls under Subpart S, so electrical work uses 1910.333(b).","step_list":["Plan the procedure and identify the sources of energy.","Deenergize the equipment and release stored energy.","Apply locks and tags to the disconnecting means, using devices strong enough to prevent accidental removal.","Use a qualified person with test equipment to verify the circuit is deenergized.","Use only the lock and tag methods in the procedure; where a lock cannot be used, additional protection is needed with a tag."],"refs":["29 CFR 1910.333(b)","29 CFR 1910.147"],"checks":[{"q":"Verification that a circuit is deenergized must be done by","opts":["A qualified person with test equipment","Anyone, by looking","A tag alone","The supervisor by phone"],"correct":0,"explain":"A qualified person verifies with test equipment.","ref":"1910.333(b)(2)"}]},{"title":"Reenergizing and release","body":"Returning equipment to service has its own steps. Removing locks and restoring power is a hazard point.","warning":"After a protective device trips, do not just close it again. 1910.334(b)(2) requires that the circuit not be reenergized until it has been determined that the equipment and circuit can be safely energized.","step_list":["Make sure tools, materials and people are clear of the equipment.","Remove temporary grounds and jumpers, and be sure guards and covers are back.","Notify affected employees that the equipment is going to be reenergized.","Each person removes their own lock and tag; follow the plant's procedure if a person is not available.","Perform a visual check before closing the disconnect."],"refs":["29 CFR 1910.333(b)","29 CFR 1910.334(b)(2)"],"checks":[{"q":"After a breaker trips on a fault, the circuit should be reenergized only after","opts":["It has been determined that it is safe to do so","The breaker is reset once","The tag is removed","Someone says it is fine"],"correct":0,"explain":"1910.334(b)(2) forbids manual reenergizing until the cause is determined.","ref":"1910.334(b)(2)"}]},{"title":"Working on or near exposed energized parts","body":"If a circuit cannot be deenergized, only qualified persons may work on or near exposed energized parts, with the appropriate precautions.","bullets":["Only qualified persons may work on or near exposed energized parts that have not been deenergized under the lockout/tagging rules.","Qualified persons must be capable of working safely on energized circuits and familiar with special precautionary techniques, personal protective equipment, insulating and shielding materials and insulated tools.","Employees must not reach into blind or enclosed spaces where energized parts may be located unless protected.","Alerting techniques such as safety signs, tags, barricades and attendants must warn and protect employees.","Portable ladders used near exposed energized parts need nonconductive side rails."],"refs":["29 CFR 1910.333(c)","29 CFR 1910.335"],"checks":[{"q":"A ladder used where it could contact exposed energized parts should have","opts":["Nonconductive side rails","Aluminum side rails","No rails","Rubber feet only"],"correct":0,"explain":"Metal ladders are conductive and a hazard.","ref":"1910.333(c)(7)"}]},{"title":"Overhead lines: 1910.333(c)(3)","body":"Overhead power lines are a leading cause of electrocutions. Unless a line has been deenergized and visibly grounded, or guarded by insulating protective equipment, minimum distances must be kept.","info":"For cranes and derricks in construction, 1926.1408 sets a 20 ft minimum clearance for lines up to 350 kV, with greater distance for higher voltage, unless other conditions are met.","bullets":["Qualified persons working near overhead lines must maintain the distances in Table S-5 unless protected.","The employer must determine the voltage before work.","Vehicles and mechanical equipment near lines have their own clearance rules."],"table":{"h":["Line voltage","Minimum clearance for unqualified persons"],"r":[["50 kV or less","10 ft (3.05 m)"],["Over 50 kV","10 ft plus 4 in (10 cm) for every 10 kV over 50 kV"]]},"refs":["29 CFR 1910.333(c)(3)","29 CFR 1926.1408"],"checks":[{"q":"Unqualified employees working near an overhead line of 50 kV or less must stay at least","opts":["10 feet away","3 feet","1 foot","20 inches"],"correct":0,"explain":"The minimum is 10 ft for 50 kV or less.","ref":"1910.333(c)(3)"}]},{"title":"Portable electric equipment: 1910.334(a)","body":"Portable cord- and plug-connected equipment must be handled and maintained to prevent damage.","bullets":["Do not carry or lower equipment by its cord.","Do not use equipment with damaged cords, or with worn or missing grounding pins.","Visually inspect cord sets and plugs before use for defects, such as insulation damage, deformed or missing pins, and external damage.","Flexible cords must be rated and used in accordance with their design.","Do not use extension cords as permanent wiring.","Grounding-type equipment must be grounded or double-insulated."],"refs":["29 CFR 1910.334(a)","29 CFR 1910.304"],"checks":[{"q":"A cord set with a missing ground pin should be","opts":["Removed from service","Used with a cheater plug","Taped","Used for light loads"],"correct":0,"explain":"Damaged cords must not be used.","ref":"1910.334(a)"}]},{"title":"Test instruments and equipment","body":"Test instruments, meters and leads should be rated for the use and inspected.","bullets":["Instruments and equipment used for testing must be visually inspected for external defects or damage before use.","Equipment with defects that could cause injury is removed from service until repaired and tested.","Use instruments rated for the circuit voltage and category.","Only qualified persons may perform testing work on circuits or equipment that may be energized."],"refs":["29 CFR 1910.334(c)"],"checks":[{"q":"Test instruments should be","opts":["Visually inspected before use for defects","Used regardless of condition","Only checked monthly","Never inspected"],"correct":0,"explain":"Visual inspection is required before use.","ref":"1910.334(c)"}]},{"title":"Electrical protective equipment and safeguards: 1910.335","body":"Employees working where there are electrical hazards must be provided with and use protective equipment appropriate for the body part and the work.","bullets":["Protective equipment includes rubber insulating gloves, sleeves, blankets, insulating tools, and shields.","Protective equipment must be maintained in a safe and reliable condition and periodically inspected or tested as required by 1910.137.","Rubber insulating gloves are tested before first issue and at intervals (generally six months in use).","Safety signs, barricades and attendants warn and protect employees where the work could create exposure.","Employers must provide the equipment; most required PPE is employer-paid under 1910.132(h)."],"refs":["29 CFR 1910.335","29 CFR 1910.137","29 CFR 1910.132(h)"],"checks":[{"q":"Rubber insulating gloves in service are generally retested every","opts":["Six months","Ten years","Never","Five years"],"correct":0,"explain":"Gloves are retested at six month intervals in use.","ref":"1910.137"}]},{"title":"Putting 1910.331-.335 into practice","body":"A quick checklist for a job on a commercial panel.","step_list":["Identify the circuit and the work.","Deenergize if possible. If not, document why.","Apply lockout/tagging and verify with test equipment.","If energized work is necessary, confirm the person is qualified, and choose PPE and tools.","Use barricades and signs; keep unqualified persons clear.","Inspect cords, tools and meters before use.","Do not reenergize until you know it is safe."],"refs":["29 CFR 1910.331-.335"]}],"quiz":[{"q":"1910.332 requires employers to","opts":["Train employees who face a risk of electric shock","Pay for licenses","Hire electricians only","Remove all labels"],"correct":0,"explain":"Training is required for employees exposed to shock risk.","ref":"1910.332"},{"q":"Table S-4 in 1910.332 lists","opts":["Typical occupations needing training","Penalties","Voltages","Clearances"],"correct":0,"explain":"It lists categories such as electricians and electrical engineers.","ref":"1910.332"},{"q":"The basic rule in 1910.333(a) is that live parts must be","opts":["Deenergized before work, unless infeasible or more hazardous","Always left energized","Tested annually","Painted"],"correct":0,"explain":"Deenergize unless infeasible or it increases the hazard.","ref":"1910.333(a)"},{"q":"Live parts at less than ___ to ground need not be deenergized if no increased exposure to burns or arc explosion exists","opts":["50 volts","10 volts","120 volts","480 volts"],"correct":0,"explain":"Under 50 volts has a limited exception.","ref":"1910.333(a)(1)"},{"q":"Electrical lockout/tagging for utilization installations is found in","opts":["1910.333(b)","1910.147 only","1910.95","1910.1200"],"correct":0,"explain":"1910.333(b) covers it.","ref":"1910.333(b)"},{"q":"Verification of deenergization is done by","opts":["A qualified person using test equipment","A tag","Visual only","Phone call"],"correct":0,"explain":"A qualified person verifies with test equipment.","ref":"1910.333(b)"},{"q":"After a protective device trips, the circuit","opts":["May not be reenergized until it is determined safe","Can be reset immediately","Should be bypassed","Can be reset three times"],"correct":0,"explain":"1910.334(b)(2).","ref":"1910.334(b)(2)"},{"q":"Only qualified persons may","opts":["Work on or near exposed energized parts","Use a flashlight","Read a meter in an office","Attend training"],"correct":0,"explain":"1910.333(c)(2).","ref":"1910.333(c)(2)"},{"q":"The minimum clearance to a line of 50 kV or less for unqualified persons is","opts":["10 feet","3 feet","6 feet","20 feet"],"correct":0,"explain":"10 ft for 50 kV or less.","ref":"1910.333(c)(3)"},{"q":"For lines over 50 kV, the clearance increases by","opts":["4 inches for every 10 kV over 50 kV","1 foot for each 5 kV","Nothing","2 inches per 100 V"],"correct":0,"explain":"10 ft plus 4 in for each 10 kV over 50 kV.","ref":"1910.333(c)(3)"},{"q":"Ladders used near energized parts should have","opts":["Nonconductive side rails","Metal rails","Wood or fiberglass is banned","No restrictions"],"correct":0,"explain":"Metal ladders conduct electricity.","ref":"1910.333(c)(7)"},{"q":"Flexible cords and cord sets should be","opts":["Visually inspected before use","Used regardless of damage","Never inspected","Used as permanent wiring"],"correct":0,"explain":"Damaged cords create shock and fire hazards.","ref":"1910.334(a)"},{"q":"Test instruments with a defect that could injure an employee must be","opts":["Removed from service until repaired and tested","Used carefully","Taped","Used on low voltage only"],"correct":0,"explain":"Remove defective test equipment.","ref":"1910.334(c)"},{"q":"Who pays for required electrical protective equipment, in most cases?","opts":["The employer","The employee","The union","The inspector"],"correct":0,"explain":"Employer-paid under 1910.132(h) with narrow exceptions.","ref":"1910.132(h)"},{"q":"Rubber insulating gloves in use are generally retested every","opts":["Six months","10 years","Never","5 years"],"correct":0,"explain":"Six months.","ref":"1910.137"},{"q":"Which warns and protects employees in electrical work areas?","opts":["Safety signs, barricades and attendants","Paint","Radios","Open doors"],"correct":0,"explain":"Alerting techniques in 1910.335.","ref":"1910.335"},{"q":"1910.147 versus 1910.333(b): which applies to electrical utilization installations?","opts":["1910.333(b)","1910.147 only","1910.95","Neither"],"correct":0,"explain":"1910.147 excludes work covered by Subpart S.","ref":"1910.147"},{"q":"Hazardous energy for non-electrical machines is controlled mainly by","opts":["1910.147","1910.333(a)","1910.269","1910.95"],"correct":0,"explain":"1910.147 is the general lockout/tagout standard.","ref":"1910.147"}]},{"title":"Construction Electrical Safety and Temporary Power","minutes":60,"overview":["Subpart K: construction electrical rules","GFCIs and the assured equipment grounding conductor program","Working near overhead lines and underground","Temporary power, cords and lighting","Hazard assessment and tools on job sites"],"slides":[{"title":"Subpart K at a glance","body":"29 CFR 1926 Subpart K covers electrical installations and safe work practices on construction sites. It uses terms and requirements similar to general industry with construction-specific rules for temporary power.","table":{"h":["Section","Topic"],"r":[["1926.402-.408","Installation safety requirements: wiring, protection, hazardous locations, special equipment"],["1926.416","General requirements for work near power circuits"],["1926.417","Lockout and tagging of circuits"],["1926.431","Maintenance of equipment"],["1926.441","Batteries and battery charging"]]},"refs":["29 CFR 1926 Subpart K"],"checks":[{"q":"Lockout and tagging of circuits on construction sites is addressed in","opts":["1926.417","1910.95","1926.20","1904"],"correct":0,"explain":"1926.417 covers it.","ref":"1926.417"}]},{"title":"Work near power circuits: 1926.416","body":"Employers must keep employees from contacting live parts unless protected, and must find out before work starts whether energized circuits are near the work.","bullets":["No employee may work near an electric power circuit that could be contacted unless protected by deenergizing and grounding or by guarding with effective means.","Before work begins, the employer must find out by inquiry, direct observation or instruments whether any energized circuit, exposed or concealed, could contact a person, tool or machine.","Employees working in confined or enclosed spaces with exposed live parts must be protected.","Protective shields and barriers should be used where needed."],"refs":["29 CFR 1926.416"],"checks":[{"q":"Before work starts, the employer must determine","opts":["Whether energized circuits could be contacted during the work","The age of the building","The paint color","The customer name"],"correct":0,"explain":"1926.416(a)(3) requires finding out.","ref":"1926.416(a)(3)"}]},{"title":"GFCI requirements on construction sites","body":"Ground-fault circuit interrupters protect against shock by opening the circuit when current leaks to ground.","bullets":["All 120-volt, single-phase, 15- and 20-ampere receptacle outlets on construction sites that are not part of permanent wiring and are in use by employees need GFCI protection.","A GFCI trips at about 5 mA of ground-fault current, much less than a breaker.","Test GFCIs with the test button before use.","Alternatively, an assured equipment grounding conductor program may be used for equipment not GFCI-protected."],"refs":["29 CFR 1926.404(b)(1)"],"checks":[{"q":"A GFCI trips at roughly how much ground fault current?","opts":["About 5 mA","About 15 A","About 100 A","About 1 A"],"correct":0,"explain":"GFCIs are designed for personal protection at about 5 mA.","ref":"1926.404"}]},{"title":"Assured equipment grounding conductor program","body":"An employer may use an assured equipment grounding conductor program (AEGCP) as an alternative to GFCIs on construction sites for receptacles not covered by GFCI protection.","info":"Check 1926.404(b)(1)(iii) for the exact testing intervals and record requirements before writing a program.","step_list":["The program is written and describes the procedures.","A competent person is designated to implement it.","Cords, plugs and receptacles are visually inspected before use each day.","Equipment grounding conductors are tested for continuity, and receptacles are tested for correct polarity.","Tests are done before first use, after repairs, after suspected damage, and at set intervals (commonly every three months, six months for fixed items not exposed to damage).","Records of the tests are kept and available."],"refs":["29 CFR 1926.404(b)(1)(iii)"],"checks":[{"q":"The AEGCP requires a","opts":["Competent person to implement the program","Plumber","Visitor","Union rep"],"correct":0,"explain":"A competent person implements the program.","ref":"1926.404"}]},{"title":"Overhead lines and cranes","body":"Contact with overhead lines is a major cause of construction electrocutions. Equipment such as cranes, lifts and dump trucks must be kept at safe distances.","warning":"A vehicle that touches a power line may be energized. The ground around it can be at a dangerous voltage.","bullets":["For cranes and derricks, 1926.1408 requires a minimum clearance of 20 ft from power lines up to 350 kV unless other approved options are used.","Identify the voltage of the line, ask the utility, and establish a safety zone.","Use a spotter and signs, and mark boundaries.","If equipment contacts a line, stay in the cab, warn others away, and call the utility. If you must leave due to fire, jump clear with feet together and shuffle away.","Ladders and scaffolds must stay clear of lines too."],"refs":["29 CFR 1926.1408","29 CFR 1926.1053"],"checks":[{"q":"If your truck touches a power line, you should generally","opts":["Stay in the cab and warn others away until the line is deenergized","Step out and run","Touch the ground and the truck","Go look at the line"],"correct":0,"explain":"Stepping out can make you the path to ground.","ref":"1926.1408"}]},{"title":"Underground utilities","body":"Digging can hit buried electric lines. Locate before you dig.","bullets":["Call 811 before digging; the locate service marks buried utilities.","Hand-dig or use vacuum excavation near marks.","Treat any unknown buried line as energized.","Protect marked lines from damage and keep records of locates."],"refs":["29 CFR 1926.651(b)"],"checks":[{"q":"Before digging, you should","opts":["Call 811 to locate underground utilities","Dig carefully","Ask a neighbor","Probe randomly"],"correct":0,"explain":"Locate calls identify buried utilities.","ref":"1926.651(b)"}]},{"title":"Temporary power and lighting","body":"Temporary wiring for construction has to be properly protected and supported.","bullets":["Use cords and cables rated for the use, with proper strain relief and protection from damage.","Do not run cords through doorways or windows where they can be pinched; keep them off the floor where possible.","Lights must be protected from breakage and have guards.","Do not use frayed or taped cords. Repair or replace.","Do not overload circuits; use rated power strips and distribution boxes.","Feeders and branch circuits for temporary power need overcurrent protection."],"refs":["29 CFR 1926.405"],"checks":[{"q":"A frayed extension cord on a job site should be","opts":["Removed from service","Taped","Used with caution","Used outdoors only"],"correct":0,"explain":"Damaged cords are a shock and fire hazard.","ref":"1926.405"}]},{"title":"Tools, ladders and cords","body":"Portable tools and ladders are used everywhere on job sites. Each presents electrical risks.","bullets":["Hand-held power tools must be double-insulated or grounded.","Do not carry tools by the cord, and do not yank the cord from the receptacle.","Metal ladders should not be used near electrical hazards. Use fiberglass.","Maintain clearance between ladders and live parts.","Wet conditions raise shock risk. Use GFCIs and weather-rated equipment."],"refs":["29 CFR 1926.302","29 CFR 1926.1053(b)(12)"],"checks":[{"q":"Which ladder is preferred where there may be electrical contact?","opts":["Fiberglass","Aluminum","Steel","Wet wood"],"correct":0,"explain":"Nonconductive ladders reduce shock risk.","ref":"1926.1053"}]},{"title":"Hazard assessment and PPE on construction sites","body":"The employer must assess hazards and provide the required protective equipment.","bullets":["A hazard assessment identifies the hazards and the PPE needed (1926.95, 1926.28).","Electrical protective equipment (rubber gloves, sleeves, insulating mats, hot sticks) is provided in accordance with 1926.97 when employees work on or near energized parts.","Employees must be trained in the use and limits of the equipment.","Damaged or outdated PPE must be replaced."],"refs":["29 CFR 1926.95","29 CFR 1926.97"],"checks":[{"q":"PPE on construction sites is based on","opts":["A hazard assessment","Guesswork","Employee preference","Cost"],"correct":0,"explain":"Hazard assessment drives PPE.","ref":"1926.95"}]},{"title":"Case study: temporary power pole","body":"A crew is working off a temporary power pole at a job site when a worker is shocked by a drill.","bullets":["The drill has a damaged cord and a missing ground pin.","The receptacle has no GFCI protection.","The worker was standing in water.","Controls that would have prevented it: GFCI protection, inspection of cords before use, removing damaged tools, keeping work areas dry.","Management: training, program enforcement and an AEGCP if GFCIs are not used."],"refs":["29 CFR 1926.404","29 CFR 1926.405"]}],"quiz":[{"q":"Construction electrical rules are in","opts":["29 CFR 1926 Subpart K","1910 Subpart S","1904","1915"],"correct":0,"explain":"Subpart K.","ref":"1926 Subpart K"},{"q":"1926.417 covers","opts":["Lockout and tagging of circuits","PPE","Cranes","Ladders"],"correct":0,"explain":"Lockout and tagging.","ref":"1926.417"},{"q":"1926.416 is about","opts":["Working near power circuits","Noise","Fall protection","Silica"],"correct":0,"explain":"It covers general requirements for work near power circuits.","ref":"1926.416"},{"q":"GFCI protection on construction sites applies to","opts":["120 V single-phase 15 and 20 amp receptacles not part of permanent wiring","All 480 V circuits","Only permanent wiring","Only offices"],"correct":0,"explain":"1926.404(b)(1)(i).","ref":"1926.404"},{"q":"A GFCI trips at about","opts":["5 mA","500 mA","5 A","50 A"],"correct":0,"explain":"About 5 mA.","ref":"1926.404"},{"q":"An AEGCP is","opts":["An alternative to GFCIs in specified conditions","A type of meter","An inspection fee","A permit"],"correct":0,"explain":"It is an alternative method.","ref":"1926.404"},{"q":"A competent person under an AEGCP","opts":["Implements the program","Signs payroll","Runs the crane","Locates utilities"],"correct":0,"explain":"A competent person implements the program.","ref":"1926.404"},{"q":"Cranes near power lines up to 350 kV must keep at least","opts":["20 feet","5 feet","10 feet","100 feet"],"correct":0,"explain":"1926.1408 requires 20 ft in the default case.","ref":"1926.1408"},{"q":"If equipment contacts a power line, the operator should","opts":["Stay in the cab and wait for the line to be deenergized","Jump out immediately","Touch the ground","Drive away"],"correct":0,"explain":"Stay put unless there is fire.","ref":"1926.1408"},{"q":"Before digging, call","opts":["811","911","411","611"],"correct":0,"explain":"811 is the national call-before-you-dig number.","ref":"1926.651"},{"q":"A frayed extension cord should be","opts":["Removed from service","Taped","Used outdoors","Used for lights only"],"correct":0,"explain":"Remove from service.","ref":"1926.405"},{"q":"Hand-held power tools must be","opts":["Double-insulated or grounded","Painted","Wet","Oiled"],"correct":0,"explain":"Double-insulated or grounded.","ref":"1926.302"},{"q":"Where electrical contact is possible, prefer ladders that are","opts":["Fiberglass","Aluminum","Steel","Wet"],"correct":0,"explain":"Nonconductive.","ref":"1926.1053"},{"q":"PPE selection starts with","opts":["A hazard assessment","A catalog","Price","Color"],"correct":0,"explain":"A hazard assessment drives PPE.","ref":"1926.95"},{"q":"The employer must find out before work whether energized circuits are near the work by","opts":["Inquiry, observation or instruments","Guessing","Skipping","Asking neighbors"],"correct":0,"explain":"1926.416(a)(3).","ref":"1926.416"},{"q":"Which risk is raised by wet conditions?","opts":["Shock","Noise","Heat","Cold"],"correct":0,"explain":"Water lowers body resistance.","ref":"OSHA"},{"q":"Rubber gloves and sleeves on construction are provided under","opts":["1926.97","1926.20","1910.95","1904"],"correct":0,"explain":"1926.97 covers electrical protective equipment.","ref":"1926.97"},{"q":"Temporary lighting should be","opts":["Guarded against breakage","Left bare","Covered with paper","Hung by the cord"],"correct":0,"explain":"Lamps should be guarded.","ref":"1926.405"}]},{"title":"PPE, Emergency Response, Arc Flash and Incident Prevention","minutes":60,"overview":["Hazard assessment and PPE under 1910.132","Electrical protective equipment under 1910.137","Arc flash and OSHA 1910.269","Emergency response and first aid","Case studies and course review"],"slides":[{"title":"Hazard assessment: 1910.132","body":"Employers must assess the workplace to determine whether hazards that need PPE are present and must certify the assessment in writing.","bullets":["The written certification identifies the workplace evaluated, the person certifying, and the date.","PPE must be selected to fit the hazard and the employee.","Employers must train employees on when PPE is needed, what to wear, how to use it, its limits and care.","Employers generally pay for required PPE with some exceptions such as ordinary safety-toe footwear and prescription safety eyewear in some cases.","Defective or damaged PPE must not be used."],"refs":["29 CFR 1910.132(d)","29 CFR 1910.132(h)"],"checks":[{"q":"The hazard assessment for PPE must be","opts":["Certified in writing","Verbal only","Optional","Done by the worker alone"],"correct":0,"explain":"1910.132(d)(2) requires written certification.","ref":"1910.132(d)"}]},{"title":"Electrical protective equipment: 1910.137","body":"This standard covers insulating gloves, sleeves, blankets, matting, covers and line hoses.","bullets":["Visually inspect before each use. Do an air test for gloves.","Use protectors over rubber gloves, except as allowed for certain classes.","Remove defective equipment from service. Do not repair rubber gloves by patching."],"table":{"h":["Item","Test frequency (in service)"],"r":[["Rubber insulating gloves","Before first issue and every six months"],["Rubber insulating sleeves","Before first issue and every twelve months"],["Rubber insulating blankets","Before first issue and every twelve months, if issued for service"],["Rubber insulating line hose and covers","Per standard and when damaged"]]},"refs":["29 CFR 1910.137"],"checks":[{"q":"Rubber insulating sleeves in service are retested generally every","opts":["Twelve months","Six months","Ten years","Never"],"correct":0,"explain":"Sleeves and blankets are generally twelve months.","ref":"1910.137"}]},{"title":"Glove classes and use","body":"Rubber insulating glove classes are rated for the voltage of the work.","keypoint":"Choose a glove whose rating is higher than the voltage of the work.","table":{"h":["Class","Maximum use AC voltage"],"r":[["00","500 V"],["0","1,000 V"],["1","7,500 V"],["2","17,000 V"],["3","26,500 V"],["4","36,000 V"]]},"refs":["29 CFR 1910.137","ASTM D120"],"checks":[{"q":"Which class of glove is rated for 1,000 V maximum use?","opts":["Class 0","Class 00","Class 1","Class 2"],"correct":0,"explain":"Class 0 is 1,000 V.","ref":"ASTM D120"}]},{"title":"Arc flash and 1910.269","body":"For electric power work covered by 1910.269, employers must assess the workplace for electric arc hazards and protect employees.","bullets":["The employer must make a reasonable estimate of the incident heat energy of an electric arc to which employees would be exposed.","Employees exposed to hazards from flames or electric arcs must not wear clothing that could melt onto the skin or ignite and continue to burn.","Where the estimated heat energy exceeds the limits, arc-rated protective clothing and equipment are required.","Face and head protection is required where an electric arc could expose the employee.","NFPA 70E offers detailed methods for estimating and controlling arc flash in other workplaces; OSHA does not adopt it as a rule."],"refs":["29 CFR 1910.269(l)(8)","NFPA 70E"],"checks":[{"q":"Under 1910.269, employees exposed to electric arcs must NOT wear clothing that","opts":["Could melt onto the skin or ignite and continue to burn","Is light colored","Is cotton","Is arc-rated"],"correct":0,"explain":"Meltable clothing worsens burns.","ref":"1910.269(l)(8)"}]},{"title":"First aid and CPR","body":"Employees must have access to prompt first aid. Electrical workers should be trained in CPR and AED use.","bullets":["1910.151(b): where there is no infirmary, clinic or hospital in near proximity, someone adequately trained must be available to render first aid.","A person working on energized equipment should not work alone where a rescue could be needed.","CPR and AED training is strongly recommended and required by many employers and by NFPA 70E for those exposed to shock.","Know the location of AEDs and first aid kits."],"refs":["29 CFR 1910.151","NFPA 70E Art. 110"],"checks":[{"q":"Where no infirmary or hospital is in near proximity, the employer must have","opts":["Someone adequately trained to render first aid","A phone number only","A printed sign","Nobody"],"correct":0,"explain":"1910.151(b).","ref":"1910.151"}]},{"title":"Responding to an electrical emergency","body":"The right response in the first minutes can save a life.","warning":"Never enter a downed-line area or touch a vehicle in contact with a line. Wait for the utility.","step_list":["Stop the current if you can do so safely: shut off the power at the source.","Call emergency services and send someone to meet them.","Do not touch the victim while the source is energized. Use an insulating object to separate them if you must.","Check responsiveness and breathing. Start CPR and use an AED if there is no pulse or breathing.","Treat burns, keep the person still, and keep them from moving if a fall is suspected.","Every electrical injury should be evaluated by a doctor, even if the person seems fine."],"refs":["NFPA 70E Art. 110","OSHA first aid resources"],"checks":[{"q":"Why should every electrical shock victim see a doctor?","opts":["Heart and internal injuries may not be obvious right away","It is cheaper","The law says nothing","Only burns matter"],"correct":0,"explain":"Delayed cardiac and internal effects can occur.","ref":""}]},{"title":"Incident investigation and prevention","body":"After an incident or close call, the employer should investigate to find root causes.","bullets":["Report all near-misses and injuries promptly.","Investigate to find the causes, not only the worker's action.","Correct the hazard and update procedures, training and PPE.","Record the incident as required (OSHA 300 log, 301 report) and report fatalities and serious injuries on time.","Share lessons learned with the crew."],"refs":["29 CFR 1904","OSH Act"],"checks":[{"q":"A good incident investigation looks for","opts":["Root causes, not only the worker's action","Someone to blame","Only the injury","The cost"],"correct":0,"explain":"Fix the system.","ref":""}]},{"title":"Case study: the assumed-dead circuit","body":"A worker is shocked while replacing a light fixture. The breaker was off, but another circuit in the box was still energized.","bullets":["What went wrong: the worker relied on the switch or breaker label and did not test.","Required practice: deenergize, lock or tag, and verify with a tested meter at the work point (1910.333(b)).","Other contributing factors: multiwire branch circuit, no lockout, no test.","Prevention: test before touch every time, label circuits, and use lockout."],"refs":["29 CFR 1910.333(b)"]},{"title":"Case study: damaged cord and no GFCI","body":"A worker using an extension cord with damaged insulation is shocked on a wet floor.","bullets":["Hazards: damaged cord, wet environment, no GFCI.","Controls: remove damaged cords, use GFCI protection, keep floors dry, use rated cords.","Training: inspect cords before use.","Supervision: enforce the program and remove equipment that fails inspection."],"refs":["29 CFR 1910.334","29 CFR 1926.404"]},{"title":"Course review","body":"The key ideas from this course.","info":"This course is for training. Use the current text of 29 CFR and your state plan to make decisions. Cited section numbers are for orientation.","step_list":["The OSH Act requires employers to protect workers; Subpart S and Subpart K set the electrical rules.","Deenergize first, lock and tag, and verify with a tested meter.","Only qualified persons work on exposed energized parts.","Keep clear of overhead lines and use GFCI or an AEGCP on construction sites.","Choose, inspect and test PPE; employers provide it.","Report fatalities within 8 hours and hospitalizations, amputations and eye loss within 24 hours."],"refs":["29 CFR 1910","29 CFR 1926"]}],"quiz":[{"q":"1910.132 requires","opts":["A written certification of the hazard assessment","Verbal approval","No records","A union vote"],"correct":0,"explain":"Written certification.","ref":"1910.132(d)"},{"q":"Who pays for most required PPE?","opts":["The employer","The employee","The union","The inspector"],"correct":0,"explain":"1910.132(h).","ref":"1910.132(h)"},{"q":"Rubber insulating gloves in service are tested every","opts":["Six months","12 months","Five years","Never"],"correct":0,"explain":"Six months.","ref":"1910.137"},{"q":"Rubber insulating sleeves in service are tested every","opts":["Twelve months","Six months","Never","Five years"],"correct":0,"explain":"Twelve months.","ref":"1910.137"},{"q":"A class 2 glove has a maximum use voltage of","opts":["17,000 V","500 V","1,000 V","7,500 V"],"correct":0,"explain":"Class 2 is 17,000 V.","ref":"ASTM D120"},{"q":"A class 00 glove has a maximum use voltage of","opts":["500 V","1,000 V","7,500 V","17,000 V"],"correct":0,"explain":"Class 00 is 500 V.","ref":"ASTM D120"},{"q":"Under 1910.269, arc-exposed employees must not wear","opts":["Clothing that could melt onto the skin","Cotton","Arc-rated clothing","Leather"],"correct":0,"explain":"Meltable clothing is prohibited.","ref":"1910.269"},{"q":"NFPA 70E is","opts":["A consensus standard, not adopted by OSHA as a rule","An OSHA regulation","A state law","A building code"],"correct":0,"explain":"OSHA does not adopt 70E.","ref":"NFPA 70E"},{"q":"1910.151(b) concerns","opts":["First aid when no infirmary or hospital is near","Noise","Ladders","Recordkeeping"],"correct":0,"explain":"First aid availability.","ref":"1910.151"},{"q":"In an electrical emergency, first","opts":["Stop the current and call for help safely","Pull the person","Wait","Run"],"correct":0,"explain":"Shut off power and call.","ref":"NFPA 70E"},{"q":"A person shocked should be evaluated by a doctor","opts":["Even if they seem fine","Only if burned","Never","Only if a manager says so"],"correct":0,"explain":"Delayed effects can occur.","ref":"OSHA"},{"q":"A near-miss should be","opts":["Reported and investigated","Ignored","Hidden","Blamed on the worker"],"correct":0,"explain":"Near-misses reveal hazards.","ref":"OSHA"},{"q":"Fatalities must be reported to OSHA within","opts":["8 hours","24 hours","1 week","30 days"],"correct":0,"explain":"8 hours.","ref":"1904.39"},{"q":"Amputations must be reported within","opts":["24 hours","8 hours","1 week","30 days"],"correct":0,"explain":"24 hours.","ref":"1904.39"},{"q":"Which is the best way to confirm a circuit is dead?","opts":["Test with a meter you have proven works","Check the breaker label","Ask a coworker","Look at the switch"],"correct":0,"explain":"Test before touch.","ref":"1910.333(b)"},{"q":"A multiwire branch circuit hazard is","opts":["Another circuit in the box may remain energized","It is always dead","It has no neutral","It is low voltage"],"correct":0,"explain":"Different circuits may share a box.","ref":"OSHA"},{"q":"Damaged cords on wet floors should be","opts":["Removed and replaced, with GFCI protection used","Taped","Ignored","Used"],"correct":0,"explain":"Remove damaged cords.","ref":"OSHA"},{"q":"Required first step in electrical work is to","opts":["Deenergize and verify","Wear gloves only","Use a ladder","Take photos"],"correct":0,"explain":"Deenergize first.","ref":"1910.333"}]}]};
